//! Wrapper of isosurface0.1.0-alpha.0 Apache-2.0 DualContouring/MinimiseQEF.
//! KNOWN LIMIT (measured, CP2/CP3): near-tangent smooth blends whose fillet radius is
//! under ~2 grid cells can produce crumpled triangles in the crease (uniform grid cannot
//! represent the feature; QEF keeps one vertex per cell). Vertex normals stay exact there
//! (analytic, 0.0deg vs FD) - the failure is geometry, not shading. Proper fix is the
//! planned octree adaptive DC unit; tests/sdf_contour_frames.rs pins today's behavior as
//! a named benchmark for it.
//! No extraction/QEF source copied. MCP adapter and error/stream mapping original.
use super::vertex_stream::Stream;#[cfg(feature="surface-contour")]use super::sdf_graph::Graph;use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Config{pub bounds:[[f64;3];2],pub resolution:u32,pub normal_epsilon:f64}
#[derive(Serialize)]pub struct Contour{pub stream:Stream,pub resolution:u32,pub sampled_field_residual_max:f64,pub topology_verified:bool,pub algorithm:&'static str,pub uv_tangent_contract:&'static str,pub empty:bool,pub welded_vertices:usize,pub boundary_edges:usize,pub nonmanifold_edges:usize,pub winding_consistent:bool,pub euler_characteristic:i64,pub signed_volume:f64,pub min_triangle_area:f64,pub sliver_triangles:usize,pub clamped_to_volume:usize,pub normal_fallbacks:usize}
#[cfg(feature="surface-contour")]
pub fn polygonize(g:&Graph,c:&Config)->Result<Contour,String>{use isosurface::{math::Vec3,distance::Signed,source::{ScalarSource,HermiteSource},sampler::Sampler,extractor::IndexedVertices,feature::MinimiseQEF,DualContouring};g.validate()?;if !(4..=64).contains(&c.resolution)||!c.normal_epsilon.is_finite()||!(1e-6..=0.01).contains(&c.normal_epsilon)||c.bounds.iter().flatten().any(|v|!v.is_finite()||v.abs()>999_000.)||(0..3).any(|j|c.bounds[1][j]<=c.bounds[0][j]){return Err("bounded volume,resolution4..64,epsilon1e-6..0.01 required".into());}
 struct Source<'a>{g:&'a Graph,c:&'a Config,error:std::cell::RefCell<Option<String>>,fallbacks:std::cell::RefCell<u32>}
 impl Source<'_>{fn point(&self,p:Vec3)->[f64;3]{let q=[p.x as f64,p.y as f64,p.z as f64];std::array::from_fn(|j|self.c.bounds[0][j]+q[j]*(self.c.bounds[1][j]-self.c.bounds[0][j]))}fn fail(&self,e:String){if self.error.borrow().is_none(){*self.error.borrow_mut()=Some(e);}}}
 impl ScalarSource for Source<'_>{fn sample_scalar(&self,p:Vec3)->Signed{crate::guard::check();match self.g.evaluate(self.point(p)){Ok(v)=>Signed(v as f32),Err(e)=>{self.fail(e);Signed(f32::NAN)}}}}
 impl HermiteSource for Source<'_>{fn sample_normal(&self,p:Vec3)->Vec3{let w=self.point(p);let r=self.g.normal_analytic(w).or_else(|_|{*self.fallbacks.borrow_mut()+=1;self.g.normal(w,self.c.normal_epsilon)});match r{Ok(n)=>{let v:[f64;3]=std::array::from_fn(|j|n[j]*(self.c.bounds[1][j]-self.c.bounds[0][j]));let n=super::vertex_stream::unit(v).unwrap_or([0.,0.,0.]);Vec3::new(n[0] as f32,n[1] as f32,n[2] as f32)},Err(e)=>{self.fail(e);Vec3::zero()}}}}
 let source=Source{g,c,error:std::cell::RefCell::new(None),fallbacks:std::cell::RefCell::new(0)};let mut positions=Vec::new();let mut indices=Vec::new();crate::guard::reserve((c.resolution as usize+1).pow(3)*128);DualContouring::new(c.resolution as usize,MinimiseQEF{}).extract(&Sampler::new(&source),&mut IndexedVertices::new(&mut positions,&mut indices));let mut normal_fallbacks=*source.fallbacks.borrow() as usize;if let Some(e)=source.error.into_inner(){return Err(e);}if positions.len()%3!=0||indices.len()%3!=0||positions.len()>3_000_000||indices.len()>3_000_000{return Err("invalid/oversize upstream contour buffers".into());}let mut vertices=Vec::new();let mut residual=0.0_f64;let mut clamped_to_volume=0usize;let mut f64_positions=Vec::with_capacity(positions.len()/3);for q in positions.chunks_exact(3){let raw:[f64;3]=std::array::from_fn(|j|q[j] as f64);let q:[f64;3]=std::array::from_fn(|j|raw[j].clamp(0.,1.));if raw!=q{clamped_to_volume+=1;}let p:[f64;3]=std::array::from_fn(|j|c.bounds[0][j]+q[j]*(c.bounds[1][j]-c.bounds[0][j]));if p.iter().any(|v|!v.is_finite()){return Err("upstream nonfinite vertex".into());}let normal=g.normal_analytic(p).or_else(|_|{normal_fallbacks+=1;g.normal(p,c.normal_epsilon)})?;f64_positions.push(p);residual=residual.max(g.evaluate(p)?.abs());let axis=if normal[0].abs()<0.8{[1.,0.,0.]}else{[0.,1.,0.]};let t=super::vertex_stream::unit([normal[1]*axis[2]-normal[2]*axis[1],normal[2]*axis[0]-normal[0]*axis[2],normal[0]*axis[1]-normal[1]*axis[0]])?;vertices.push(super::primitives::Vertex{position:p.map(|v|v as f32),normal:normal.map(|v|v as f32),uv:[0.,0.],tangent:[t[0] as f32,t[1] as f32,t[2] as f32,1.]});}// upstream emits inward (CW) winding; flip to CCW-outward to match the outward analytic vertex normals.
 let tri_indices:Vec<[u32;3]>=indices.chunks_exact(3).map(|i|[i[0],i[2],i[1]]).collect();let cen=super::topo::census(&f64_positions,&tri_indices);let empty=tri_indices.is_empty();let stream=Stream{vertices,indices:tri_indices};if !empty{stream.validate()?;}let verified=!empty&&cen.boundary_edges==0&&cen.nonmanifold_edges==0&&cen.winding_consistent&&cen.signed_volume>0.;Ok(Contour{stream,resolution:c.resolution,sampled_field_residual_max:residual,topology_verified:verified,algorithm:"isosurface DualContouring + MinimiseQEF, analytic Hermite normals (FD fallback)",uv_tangent_contract:"UV=(0,0), orthonormal arbitrary tangent; no texture parameterization",empty,welded_vertices:cen.welded_vertices,boundary_edges:cen.boundary_edges,nonmanifold_edges:cen.nonmanifold_edges,winding_consistent:cen.winding_consistent,euler_characteristic:cen.euler_characteristic,signed_volume:cen.signed_volume,min_triangle_area:cen.min_triangle_area,sliver_triangles:cen.sliver_triangles,clamped_to_volume,normal_fallbacks})}
#[cfg(all(test,feature="surface-contour"))]mod tests{use super::*;use crate::threed::sdf_graph::Field;#[test]fn wrapped_sphere_resolution_residual_and_vertex_abi(){let g=Graph{nodes:vec![Field::Sphere{center:[0.;3],radius:1.}],output:0};let c=Config{bounds:[[-1.5;3],[1.5;3]],resolution:12,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();m.stream.validate().unwrap();
assert_eq!(std::mem::size_of::<super::super::primitives::Vertex>(),48);assert!(m.sampled_field_residual_max.is_finite());assert!(m.topology_verified&&m.euler_characteristic==2,"sphere: v={} e={} b={} nm={} wind={} vol={} slivers={} clamped={} fb={}",m.topology_verified,m.euler_characteristic,m.boundary_edges,m.nonmanifold_edges,m.winding_consistent,m.signed_volume,m.sliver_triangles,m.clamped_to_volume,m.normal_fallbacks);assert_eq!((m.normal_fallbacks,m.sliver_triangles,m.clamped_to_volume),(0,0,0),"sphere telemetry: fb={} slivers={} clamped={}",m.normal_fallbacks,m.sliver_triangles,m.clamped_to_volume);} #[test]fn smooth_csg_fixture_counts_finite_and_residual_bounded(){let g=Graph{nodes:vec![Field::Sphere{center:[0.35,0.,0.],radius:0.8},Field::Box{center:[-0.35,0.,0.],half_size:[0.6;3]},Field::SmoothUnion{a:0,b:1,k:0.25}],output:2};let c=Config{bounds:[[-1.6;3],[1.6;3]],resolution:20,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();m.stream.validate().unwrap();assert!(m.stream.vertices.len()>=100&&m.stream.indices.len()>=100,"degenerate contour v={} i={}",m.stream.vertices.len(),m.stream.indices.len());assert!(m.stream.vertices.len()<=1_000_000);let cell=(c.bounds[1][0]-c.bounds[0][0])/c.resolution as f64;assert!(m.sampled_field_residual_max.is_finite()&&m.sampled_field_residual_max<2.*cell,"residual {} cell {}",m.sampled_field_residual_max,cell);assert!(m.stream.vertices.iter().all(|v|v.position.iter().chain(v.normal.iter()).all(|x|x.is_finite())));assert!(m.algorithm.contains("DualContouring")&&m.uv_tangent_contract.contains("no texture"));assert!(m.topology_verified&&m.euler_characteristic==2,"smooth-union: v={} e={} b={} nm={} vol={} slivers={} clamped={}",m.topology_verified,m.euler_characteristic,m.boundary_edges,m.nonmanifold_edges,m.signed_volume,m.sliver_triangles,m.clamped_to_volume);}
 #[test]fn sharp_box_vertices_stay_in_volume_and_zero_gradient_is_typed_error(){let g=Graph{nodes:vec![Field::Box{center:[0.;3],half_size:[0.6;3]}],output:0};let c=Config{bounds:[[-1.6;3],[1.6;3]],resolution:8,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();m.stream.validate().unwrap();assert!(m.stream.indices.len()>=12,"box contour too small i={}",m.stream.indices.len());for v in &m.stream.vertices{for j in 0..3{assert!(v.position[j]>=c.bounds[0][j] as f32-1e-3&&v.position[j]<=c.bounds[1][j] as f32+1e-3,"vertex escapes volume: {:?}",v.position);}}
 let sphere=Graph{nodes:vec![Field::Sphere{center:[0.;3],radius:1.}],output:0};assert!(sphere.normal([0.;3],0.001).is_err(),"zero gradient must error, not NaN");let cell=(c.bounds[1][0]-c.bounds[0][0])/c.resolution as f64;for corner in 0..8{let t=[if corner&1==0{-0.6}else{0.6},if corner&2==0{-0.6}else{0.6},if corner&4==0{-0.6}else{0.6}];let d=m.stream.vertices.iter().map(|v|{let dx=v.position[0] as f64-t[0];let dy=v.position[1] as f64-t[1];let dz=v.position[2] as f64-t[2];(dx*dx+dy*dy+dz*dz).sqrt()}).fold(f64::INFINITY,f64::min);assert!(d<cell,"corner {:?} nearest vertex {} >= cell {}",t,d,cell);}assert!(m.topology_verified,"box: v={} b={} nm={} wind={} vol={} slivers={} clamped={}",m.topology_verified,m.boundary_edges,m.nonmanifold_edges,m.winding_consistent,m.signed_volume,m.sliver_triangles,m.clamped_to_volume);}
 #[test]fn torus_genus_one_euler_zero(){let g=Graph{nodes:vec![Field::Torus{center:[0.;3],major_radius:1.,minor_radius:0.4}],output:0};let c=Config{bounds:[[-1.6;3],[1.6;3]],resolution:24,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();let expect=2.*std::f64::consts::PI*std::f64::consts::PI*1.*0.4*0.4;assert!(m.topology_verified&&m.euler_characteristic==0,"torus: v={} e={} b={} nm={} wind={} vol={} slivers={} clamped={} fb={}",m.topology_verified,m.euler_characteristic,m.boundary_edges,m.nonmanifold_edges,m.winding_consistent,m.signed_volume,m.sliver_triangles,m.clamped_to_volume,m.normal_fallbacks);assert!((m.signed_volume-expect).abs()<0.1*expect,"torus volume {} vs analytic {}",m.signed_volume,expect);}
 #[test]fn empty_field_is_a_result_not_an_error(){let g=Graph{nodes:vec![Field::Sphere{center:[10.,10.,10.],radius:1.}],output:0};let c=Config{bounds:[[-1.5;3],[1.5;3]],resolution:12,normal_epsilon:0.001};let m=polygonize(&g,&c).unwrap();assert!(m.empty&&m.stream.vertices.is_empty()&&m.stream.indices.is_empty()&&!m.topology_verified,"empty field must be a typed empty result: empty={} v={}",m.empty,m.stream.vertices.len());}
}
